def mse(w, b, xs, ys):
    total = 0
    for i in range(len(xs)):
        e = w * xs[i] + b - ys[i]
        total = total + e * e
    return total / len(xs)

def nudge_once(w, b, xs, ys, step):
    best = mse(w, b, xs, ys)
    up = mse(w + step, b, xs, ys)
    down = mse(w - step, b, xs, ys)
    if up < best and up <= down:
        w, best = w + step, up
    elif down < best:
        w, best = w - step, down
    up = mse(w, b + step, xs, ys)
    down = mse(w, b - step, xs, ys)
    if up < best and up <= down:
        b, best = b + step, up
    elif down < best:
        b, best = b - step, down
    return (w, b)

def fit_by_nudging(xs, ys, step):
    w, b, rounds = 0.0, 0.0, 0
    while True:
        new_w, new_b = nudge_once(w, b, xs, ys, step)
        rounds = rounds + 1
        if new_w == w and new_b == b:
            break
        w, b = new_w, new_b
    w, b = round(w, 6), round(b, 6)
    return (w, b, round(mse(w, b, xs, ys), 6), rounds)

